'use strict';
(()=>{
 const L=window.CombatLab,D=window.GameData,$=id=>document.getElementById(id),spectator=new window.Spectator(),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const visible=L.visibleScenarios||Object.keys(L.scenarios);
 let key=visible[0],battle,done=false,manualCards=0,last=0,accum=0,busy=false,selectionError='',intervened=false,handKey='';const results={};
 $('run-all').textContent=visible.length===1?'오토 기준 결과 계산':'세 전투 오토 비교';
 $('scenarios').innerHTML=visible.map(id=>{const p=L.scenarios[id];return `<button data-scenario="${id}" aria-pressed="false"><strong>${p.name}</strong><span>${p.goal}</span></button>`;}).join('');
 const usesHtml=uses=>uses.map(x=>`<span class="chip">${D.cards[x.key].name} ${x.n}회${x.damage>0?' · 피해 '+Math.round(x.damage):''}</span>`).join(' ')||'카드 사용 없음';
 function resultHtml(r){if(!r)return '<p class="note">아직 결과가 없습니다.</p>';const hp=Math.round(r.hp.reduce((n,a)=>n+a.hp,0)),alive=r.hp.filter(a=>a.hp>0).length;return `<div class="result-run"><strong>${r.method} · ${r.status} · ${r.time.toFixed(1)}초</strong><p>생존 ${alive}/4 · 남은 HP ${hp}</p><dl><dt>받은 피해</dt><dd>${Math.round(r.received.reduce((n,x)=>n+x,0))}</dd><dt>회복량</dt><dd>${Math.round(r.healed)}</dd><dt>분담한 피해</dt><dd>${Math.round(r.shared)}</dd><dt>카드 차단</dt><dd>${r.blocked}회</dd><dt>카드 사용</dt><dd>${r.cards}회 · 직접 ${r.manualCards}회</dd></dl><p>${r.hp.map((a,i)=>`${a.name} ${Math.round(r.received[i])}${a.hp<=0?' · 전투불능':''}`).join(' / ')}</p><p>${usesHtml(r.uses)}</p>${r.mechanic?`<p class="note">낙하 예고 ${r.mechanic.casts}회 · 피격 누적 ${r.mechanic.hits}회 · 범위 밖 누적 ${r.mechanic.dodges}회 · 카드 이동 ${r.mechanic.rescued+r.mechanic.repositioned}회 · 빈틈 중 피해 ${Math.round(r.mechanic.windowDamage)}</p>`:''}${window.BattleAwareness.recap(r)}</div>`;}
 function renderResults(){$('results').innerHTML=visible.map(id=>{const r=results[id]||{};return `<article class="result-card" data-result="${id}"><h3>${L.scenarios[id].name}</h3><small>오토 기준</small>${resultHtml(r.auto)}${r.play?`<small>최근 직접 플레이</small>${resultHtml(r.play)}`:''}</article>`;}).join('');}
 function storeResult(r){results[r.scenario]??={};results[r.scenario][r.method==='오토'?'auto':'play']=r;renderResults();}
 function start(id){key=id;battle=L.create(id,$('control').value);done=false;manualCards=0;intervened=$('control').value==='manual';handKey='';accum=0;selectionError='';for(const button of document.querySelectorAll('[data-scenario]'))button.setAttribute('aria-pressed',String(button.dataset.scenario===id));$('goal').textContent=L.scenarios[id].goal;update();paint();}
 function finish(){if(done)return;done=battle.s.ended||battle.s.t>=L.duration-1e-8;if(done)storeResult(L.summarize(battle,manualCards,intervened));}
 function paint(){spectator.draw($('field'),battle,$('moment'));}
 function update(){const s=battle.s;$('control').value=s.control;$('lab-status').textContent=`${L.scenarios[key].name} · ${s.t.toFixed(1)} / ${L.duration}초${done?' · '+(s.ended?s.winner===0?'승리':'패배':'시간 종료'):s.paused?' · 일시정지':''}`;$('pause').textContent=s.paused?'계속 보기':'잠시 멈춤';$('pause').disabled=done;$('presentation').textContent=spectator.director.mode==='full'?'연출 전체':'연출 간소';$('presentation').setAttribute('aria-pressed',String(spectator.director.mode==='simple'));$('sound').textContent=spectator.sound?'소리 끄기':'소리 켜기';$('sound').setAttribute('aria-pressed',String(spectator.sound));
  const incoming=s.events.filter(e=>e.side===1&&window.GameCore.offense.includes(e.kind));$('incoming').innerHTML=incoming.map(e=>`<span>${D.cards[e.key]?.name||D.hostile[e.key].name} → ${e.kind==='area'?'범위 공격':esc(battle.eventTarget(e)?.name||'대상 소실')} · ${Math.max(0,e.at-s.t).toFixed(1)}초</span>`).join('')||'<span>예고된 적 카드 공격 없음</span>';
  $('party-health').innerHTML=s.actors.filter(a=>a.side===0).map(a=>`<div class="${a.hp<=0?'down':''}"><strong>${a.name}</strong><span>${a.hp<=0?'전투불능':Math.ceil(a.hp)+' / '+a.max}</span><div class="bar"><span style="width:${a.hp/a.max*100}%"></span></div></div>`).join('');
  $('metrics').innerHTML=[['회복량',Math.round(s.stats.healed[0])],['분담한 피해',Math.round((s.stats.protected?.[0]||0)+s.stats.covered)],['카드 차단',s.stats.blocked[0]],['카드 사용',Object.values(s.stats.cards[0]).reduce((n,x)=>n+x,0)]].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('');
  $('command-status').textContent=done?'전투가 종료됐습니다. 결과 비교에서 사용한 카드와 피해를 확인하세요.':s.ready?'명령 준비 완료 · 카드를 선택하면 시간을 멈추고 개입합니다.':`다음 명령까지 ${Math.max(0,s.due-s.t).toFixed(1)}초 · 기본 행동은 자동으로 진행합니다.`;
  const handStamp=s.decks[0].hand.map(c=>c.id).join('/')+'/'+s.selected+'/'+s.ready+'/'+done;if(handKey!==handStamp){handKey=handStamp;$('hand').innerHTML=s.decks[0].hand.map(c=>`<button data-card="${c.id}" ${done||!s.ready?'disabled':''} class="${s.selected===c.id?'active':''}"><strong>${D.cards[c.key].name}</strong><small>${D.roles[D.cards[c.key].role].name} · ${D.cards[c.key].time}초</small></button>`).join('');}
  const card=s.decks[0].hand.find(c=>c.id===s.selected),d=card&&battle.definition(card),caster=card&&battle.caster(card);$('selected').textContent=d?d.name+' · '+d.desc+' · 명령 회복 '+d.time+'초 · 발동 '+battle.preparation(card,s.target,0).toFixed(1)+'초'+(d.duration?' · 효과 유지 '+d.duration+'초':''):'원하는 카드가 준비되면 선택하세요.';const targets=d?(d.self?[caster]:window.GameCore.friendly.includes(d.kind)?battle.alive(0).filter(a=>(!['serin_cover','boss_rescue'].includes(card.key)||a.id!==caster.id)&&(card.key!=='boss_rescue'||battle.inside(a))):window.GameCore.targeted(d)?battle.alive(1):[]):[];$('targets').innerHTML=targets.map(a=>`<button data-target="${a.id}" ${s.target===a.id?'class="active"':''}>${a.name} ${Math.ceil(a.hp)}</button>`).join('');
  const check=card&&battle.commandCheck(0,card.id,s.target);$('confirm').disabled=done||!s.paused||!check?.ok;$('reroll').disabled=done||!battle.canReroll();$('reroll').textContent='선택 카드 교체 · '+s.rerolls+'회';$('wait').disabled=done||!s.ready||s.control!=='manual';$('resume').disabled=done||s.control==='auto'&&!s.paused;$('lab-message').textContent=selectionError||(check&&!check.ok?check.error:'');
  if(s.control==='auto'&&s.autoHold?.phase==='holding'&&!s.paused)$('command-status').textContent='오토 · '+s.autoHold.reason;
  $('battle-awareness').innerHTML=window.BattleAwareness.panel(battle)+(battle.s.mechanic?'<p class="note">피격 누적 '+battle.s.mechanic.stats.hits+'회 · 범위 밖 누적 '+battle.s.mechanic.stats.dodges+'회 · 카드 이동 '+(battle.s.mechanic.stats.rescued+battle.s.mechanic.stats.repositioned)+'회 · 빈틈 중 피해 '+Math.round(battle.s.mechanic.stats.windowDamage)+'</p>':'');
  $('battle-log').innerHTML=s.logs.slice(0,16).map(x=>`<p>${x.at.toFixed(1)}초 · ${esc(x.text)}</p>`).join('');
 }
 function step(dt){if(done)return;battle.step(Math.min(dt,Math.max(0,L.duration-battle.s.t)));finish();update();paint();}
 async function compare(){if(busy)return;busy=true;$('run-all').disabled=true;try{let count=0;for(const id of visible){const b=L.create(id);$('comparison-status').textContent=`${++count}/${visible.length} · ${L.scenarios[id].name} 오토 비교 중`;for(let i=0;i<L.duration/.02&&!b.s.ended;i++){b.step(.02);if(i%250===0)await new Promise(resolve=>setTimeout(resolve,0));}storeResult(L.summarize(b));}$('comparison-status').textContent='선택 가능한 전투의 오토 결과를 계산했습니다. 직접 플레이한 결과도 나란히 남습니다.';}finally{busy=false;$('run-all').disabled=false;}}
 $('scenarios').onclick=e=>{const button=e.target.closest('[data-scenario]');if(button)start(button.dataset.scenario);};$('control').onchange=()=>start(key);$('restart').onclick=()=>start(key);$('pause').onclick=()=>{battle.pause();update();paint();};$('resume').onclick=()=>{battle.resumeAuto();selectionError='';update();paint();};$('wait').onclick=()=>{intervened=true;battle.wait();update();paint();};$('hand').onclick=e=>{const button=e.target.closest('[data-card]');if(button&&!button.disabled){battle.select(button.dataset.card);selectionError='';update();paint();}};$('targets').onclick=e=>{const button=e.target.closest('[data-target]');if(button){battle.target(button.dataset.target);update();paint();}};$('confirm').onclick=()=>{if(battle.confirm()){manualCards++;selectionError='';finish();}else selectionError=battle.commandCheck(0,battle.s.selected,battle.s.target).error;update();paint();};$('reroll').onclick=()=>{intervened=true;battle.reroll();update();paint();};$('sound').onclick=async()=>{await spectator.setSound(!spectator.sound);update();};$('presentation').onclick=()=>{spectator.director.setMode(spectator.director.mode==='full'?'simple':'full');update();paint();};$('run-all').onclick=compare;
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&!done&&!battle.s.paused){battle.pause();update();}});window.addEventListener('pagehide',()=>spectator.setSound(false));
 $('deck').innerHTML=Object.entries(L.deck().reduce((rows,c)=>{rows[c.key]=(rows[c.key]||0)+1;return rows;},{})).map(([id,n])=>`<span class="chip">${D.cards[id].name} ${n}장</span>`).join(' ');function frame(now){const dt=Math.min(.1,(now-last)/1000||0);last=now;if(!done&&!battle.s.paused){accum+=dt;while(accum>=.02){step(.02);accum-=.02;}}paint();requestAnimationFrame(frame);}
 window.combatLab={get battle(){return battle;},get done(){return done;},get scenario(){return key;},get results(){return results;},start,step,compare,spectator};renderResults();start(key);requestAnimationFrame(frame);
})();
